/**
 * JMComic3（com.a7m3p9xv.t6qk2z8.app）去广告 LSPosed 模块（Kotlin / libxposed API 102）。
 *
 * 双层拦截：
 *  1) 网络层：Hook Capacitor WebViewClient(com.getcapacitor.q) 与 ServiceWorkerClient
 *     (com.getcapacitor.d) 的 shouldInterceptRequest，命中广告 API 返回伪造"空广告"响应
 *     {code:200, data:AES(空载荷)}，前端 HttpUtil 可正常解密。
 *  2) 页面层：Hook onPageStarted/onPageFinished 注入 JS——fetch 短路到预置响应、
 *     持续强制 memberInfo.ad_free=true、自动跳过开屏覆盖层链（选线自动 + 年龄确认/X 自动点）。
 * 广告端点解密密钥 = md5("185Hcomic3PAPP7R")（与时间无关，见 reversed_src/api/HttpUtil.ts）。
 * 3) 繁→简：assets/t2s.js（OpenCC TS 字表+短语表）base64 内嵌进 dex，注入主框架。
 * 4) DexKit 兜底：硬编码类名失效时按结构签名（继承 + 方法签名）在宿主 dex 重新定位；
 *    so 只在失败路径加载——正常启动零 DexKit 开销。
 * 5) API 102：XposedModule 入口 + META-INF/xposed/ 声明；Hooker/Chain 拦截器链；
 *    热重载 setId/replaceHook 原子接管；ExceptionMode.PROTECTIVE 防崩宿主。
 * 6) 功能开关：Config（libxposed RemotePreferences）——去广告 / 繁简 / 签到 / 补签 / 自动跳线。
 * 广告端点与前端期望载荷（已逐一核对消费方）：
 *   ad_content_all -> {}  advertise_all -> {"img":{}}  advertise -> {"adv":[]}  ad_content -> {"adv":[]}
 */
class MainHook : XposedModule() {
    companion object {
        /** 目标 App 包名（改这里！同时必须改 resources/META-INF/xposed/scope.list） */
        const val TARGET_PKG = "com.a7m3p9xv.t6qk2z8.app"
        /** 日志前缀（与 README 排错说明保持一致） */
        const val TAG = "[hook-JMComic3]"
        /** 前端 apiPaths.token——AES 密钥种子 */
        private const val KEY_SEED = "185Hcomic3PAPP7R"
        // hook 稳定 id（API 102 setId）：热重载时新代按 id 把旧 handle 无缝换成新 hooker
        private const val H_SIR_WEBVIEW = "jm.sir.webview"   // afterIntercept(1)
        private const val H_SIR_SW = "jm.sir.sw"             // afterIntercept(0)
        private const val H_PAGE = "jm.page"                 // pageHooker（start/finish 加后缀）
        private const val H_ATTACH = "jm.attach"             // Application.attach
        /** 框架接口静态引用（onModuleLoaded 捕获；静态工具借它走现代日志）。 */
        @Volatile
        private var sApi: XposedInterface? = null
        /** 进程名（onModuleLoaded 记录；用于主进程判断）。 */
        @Volatile
        private var sProcessName: String = ""
        /** 统一日志：XposedInterface.log（现代 API 没有 XposedBridge）。 */
        @JvmStatic
        fun log(msg: String) {
            sApi?.log(Log.INFO, TAG, msg)
        }
        /** libdexkit.so 是否已加载（每进程一次；只在硬编码类名失效的兜底路径才加载）。 */
        private var sDexKitLoaded = false
        /** 繁→简脚本解码缓存；每进程只解一次。 */
        @Volatile
        private var sT2sJs: String? = null
        @Volatile
        private var sT2sTried = false
        /**
         * 内嵌繁→简脚本（构建时从 assets/t2s.js 生成的 base64）。
         * 不运行时读模块 APK：宿主对模块包有可见性限制、Android 12+ 安装布局扫目录落空——内嵌零依赖。
         */
        private const val T2S_B64 = ""
        /**
         * 注入 JS 补丁模板（页面提交/结束时 evaluate；补丁自身幂等）。
         * @@ 占位符由 buildPatch 按开关替换：ADFREE 强制 ad_free / FETCH 短路桥 /
         * APIURL 选线捷径+扫描器重启 / SCANNER 页面就绪自启 / B_* 预置响应体。
         */
        private val JS_TEMPLATE: String = """
       (function () {
          if (window.__jmAdOff) return;
          window.__jmAdOff = 1;

          // ① 持续强制 ad_free=true。
          //    必须在 localStorage.setItem 上加钩子：登录 / 服务端刷新会用 saveAuthData()
          //    把整个 memberInfo 重写一遍（Hooks/useAuth.tsx），一次性写入会被覆盖回 false
          //    （真机 leveldb 实读确认过：ad_free:false 覆盖了模块写入的 true）。
          //    这里对所有写入 memberInfo 的路径统一注入，并把 setItem 再包二层暴露的
          //    __jmAdFreeSet 供下面立即调用一次。
          function enforceAdFree(raw) {
            try {
              if (typeof raw !== "string") return raw;
              var o = JSON.parse(raw);
              if (!o || typeof o !== "object") return raw;
              if (o.ad_free === true) return raw;
              o.ad_free = true;
              return JSON.stringify(o);
            } catch (e) { return raw; }
          }
          try {
            var proto = window.localStorage;
            var origSet = proto.setItem;
            proto.setItem = function (k, v) {
              if (k === "memberInfo") { @@ADFREE@@ }
              var r = origSet.call(this, k, v);
              if (k === "apiUrl") { @@APIURL@@ }
              return r;
            };
            // 顺手清掉缓存的广告数据（旧的在 localStorage，新的全走内存）
            try { proto.removeItem("adsList"); proto.removeItem("adsContent"); } catch (e) {}
            // 立即对现存条目生效一次
            var cur = proto.getItem("memberInfo");
            if (cur) { proto.setItem("memberInfo", cur); }
          } catch (e) {}
          var B_ALL = '{"code":200,"data":"dX0+bVp3SRiz9JgJKje5Gw=="}';
          var B_COVER = '{"code":200,"data":"CtZUA5QbalyVB/YxnPxZOw=="}';
          var B_ADV = '{"code":200,"data":"ku+aFsRa0uSQotUOdIDQqg=="}';
          function bodyFor(u) {
            if (typeof u !== "string") return null;
            var p = u.split("?")[0].split("#")[0];
            var s = p.substring(p.lastIndexOf("/") + 1);
            if (s === "ad_content_all") return B_ALL;
            if (s === "advertise_all") return B_COVER;
            if (s === "advertise") return B_ADV;
            if (s === "ad_content") return B_ADV;
            return null;
          }
          @@FETCH@@

          // ③ 选线后自动跳过开屏覆盖层（FirstCover 选完线路 -> 直接进正文）。
          //    覆盖层链：SecondCover 的 X（3 秒后才出现）、ThreeCover/FourCover 的
          //    "我已年滿18歲" 大按钮与 X —— 点它们走宿主自己的 handleAction，
          //    由 React 状态机推进到正文（coverOpen=6），绝不去伪造内部状态。
          //    只点"全屏 z-50 覆盖容器里的 button"：广告链接是 a/Link，碰不到；
          //    FirstCover 自己的线路按钮（rounded-full w-2/5）与退出对话框不在匹配形状内。
          var skipTimer = null;
          var routeAutoPicked = false;
          // 预写捷径：apiUrl 是宿主持久化的上次选定线路。有它 = 老用户回访，
          // 直接写 state=true（与 ThreeCover.handleAction 同键同值），Main.tsx 挂载时
          // 的 useEffect([mainStatus]) 会 setCoverOpen(6) 一步进正文，选线页根本不出现。
          // 想换线路走 个人中心→SpeedTest（宿主自带）。首次安装无 apiUrl 时不预写，
          // 由 autoPickRoute 代点第一条（宿主 App.tsx 本来就是随机选线，等价）。
          try {
            if (localStorage.getItem("apiUrl")) {
              sessionStorage.setItem("state", JSON.stringify(true));
            }
          } catch (e) {}
          function coverInFullScreen(el) {
            for (var p = el; p && p !== document.body; p = p.parentElement) {
              var c = typeof p.className === "string" ? p.className : "";
              if (c.indexOf("z-50") >= 0 && (c.indexOf("absolute left-0 top-0") >= 0 || c.indexOf("fixed inset-0") >= 0)) return true;
            }
            return false;
          }
          function clickCoverButtons() {
            var bs = document.querySelectorAll("button");
            for (var j = 0; j < bs.length; j++) {
              var b = bs[j];
              if (b.disabled || !coverInFullScreen(b)) continue;
              var cn = typeof b.className === "string" ? b.className : "";
              var age = cn.indexOf("bg-og") >= 0 && cn.indexOf("w-4/5") >= 0;
              var close = cn.indexOf("rounded-3xl") >= 0 && cn.indexOf("w-8") >= 0 && cn.indexOf("h-8") >= 0;
              if (age || close) { b.click(); }
            }
          }
          // 选线页自动挑第一条线路：宿主 App.tsx 本来也是 getRandomItems 随机选线，
          // 列表顺序即宿主自己的候选序。只在本次注入周期里点一次（routeAutoPicked），
          // 点了之后 apiUrl 写入会接着触发 state=true 捷径 + 覆盖层扫描。
          function autoPickRoute() {
            if (routeAutoPicked) return;
            try { if (localStorage.getItem("apiUrl")) return; } catch (e) {}
            if (!document.body || document.body.innerText.indexOf("请选择网络") < 0
                && document.body.innerText.indexOf("請選擇網路") < 0) return;
            var bs = document.querySelectorAll("button");
            for (var j = 0; j < bs.length; j++) {
              var cn = typeof bs[j].className === "string" ? bs[j].className : "";
              // FirstCover 线路按钮形状：rounded-full w-2/5 p-3 mb-5（覆盖层里没有别的这个组合）
              if (cn.indexOf("rounded-full") >= 0 && cn.indexOf("w-2/5") >= 0 && !bs[j].disabled) {
                routeAutoPicked = true;
                bs[j].click();
                return;
              }
            }
          }
          function startCoverSkip() {
            if (skipTimer) { clearInterval(skipTimer); }
            var until = Date.now() + 20000;
            skipTimer = setInterval(function () {
              if (Date.now() > until) { clearInterval(skipTimer); skipTimer = null; return; }
              try { autoPickRoute(); clickCoverButtons(); } catch (e) {}
            }, 150);
          }
          @@SCANNER@@
        })();
""".trimIndent()
        /** 组装本次注入的 JS：按开关裁剪占位符。 */
        private fun buildPatch(): String {
            val adBlock = Config.enabled(Config.K_AD_BLOCK)
            val autoSkip = Config.enabled(Config.K_AUTO_SKIP)
            val q = '"'
            return JS_TEMPLATE
                .replace("@@ADFREE@@", if (adBlock) "v = enforceAdFree(v);" else "")
                .replace(
                    "@@FETCH@@",
                    if (adBlock)
                        "var origFetch = window.fetch;" +
                        "if (typeof origFetch === " + q + "function" + q + ") {" +
                        "window.fetch = function (input) {" +
                        "try {" +
                        "var u = (typeof input === " + q + "string" + q + ") ? input : (input && input.url) || " + q + q + ";" +
                        "var b = bodyFor(u);" +
                        "if (b !== null) {" +
                        "return Promise.resolve(new Response(b, { status: 200, statusText: " + q + "OK" + q + ", headers: { " + q + "Content-Type" + q + ": " + q + "application/json" + q + " } }));" +
                        "}" +
                        "} catch (e) {}" +
                        "return origFetch.apply(this, arguments);" +
                        "};" +
                        "}"
                    else ""
                )
                .replace(
                    "@@APIURL@@",
                    if (autoSkip)
                        "try { sessionStorage.setItem(" + q + "state" + q + ", JSON.stringify(true)); startCoverSkip(); } catch (e) {}"
                    else ""
                )
                .replace("@@SCANNER@@", if (autoSkip) "try { startCoverSkip(); } catch (e) {}" else "")
        }
        /** 解码内嵌繁→简脚本并缓存；失败只影响繁→简，去广告不受影响。 */
        private fun t2sScript(): String? {
            if (sT2sTried) return sT2sJs
            synchronized(MainHook::class.java) {
                if (sT2sTried) return sT2sJs
                sT2sTried = true
                try {
                    sT2sJs = String(Base64.decode(T2S_B64, 0), StandardCharsets.UTF_8)
                } catch (t: Throwable) {
                    log(TAG + " 繁→简脚本解码失败: " + t)
                }
                val js = sT2sJs
                log(TAG + " 繁→简转换 " + (if (js != null) "已启用 (" + js.length + " 字符)"
                    else "不可用（内嵌脚本解码失败），仅保留去广告"))
            }
            return sT2sJs
        }
        /**
         * DexKit 兜底：找「继承 superCls 且声明 method(paramTypes)」的类；
         * 多候选取类名最短者（R8 短名特征）。参数点分全名，与 MethodMatcher 约定一致。
         */
        private fun dexKitFindClass(loader: ClassLoader, sourceDir: String?,
                                   superCls: String, method: String, vararg paramTypes: String): Class<*>? {
            try {
                if (!sDexKitLoaded) {
                    System.loadLibrary("dexkit")
                    sDexKitLoaded = true
                }
            } catch (t: Throwable) {
                log(TAG + " DexKit so 加载失败: " + t)
                return null
            }
            if (sourceDir == null) {
                log(TAG + " DexKit：sourceDir 为空，跳过")
                return null
            }
            var best: String? = null
            try {
                DexKitBridge.create(sourceDir).use { bridge ->
                    val list = bridge.findMethod(
                        FindMethod.create().matcher(MethodMatcher.create().name(method).paramTypes(*paramTypes))
                    )
                    for (md in list) {
                        val c = try {
                            md.getClassInstance(loader)
                        } catch (ignore: Throwable) {
                            continue
                        }
                        var hit = false
                        var p: Class<*>? = c
                        while (p != null) {
                            if (p.name == superCls) {
                                hit = true
                                break
                            }
                            p = p.superclass
                        }
                        if (!hit) continue
                        val cn = c.name
                        val b = best
                        if (b == null || cn.length < b.length) best = cn
                    }
                }
            } catch (t: Throwable) {
                log(TAG + " DexKit 搜索失败: $t")
                return null
            }
            val name = best
            if (name == null) {
                log(TAG + " DexKit 未找到继承 " + superCls + " 的 " + method + " 方法")
                return null
            }
            return try {
                val c = Class.forName(name, false, loader)
                log(TAG + " DexKit 定位 " + name + "（继承 " + superCls + "）")
                c
            } catch (t: Throwable) {
                log(TAG + " DexKit 类加载失败 " + name + ": " + t)
                null
            }
        }
        /** 广告 API 路径 → 前端期望的明文载荷；非广告端点返回 null。 */
        private fun adPayloadFor(uri: Uri?): String? {
            val path = uri?.path ?: return null
            if (path.isEmpty()) return null
            val slash = path.lastIndexOf('/')
            val q = '"'
            return when (if (slash >= 0) path.substring(slash + 1) else path) {
                "ad_content_all" -> "{}"
                "advertise_all" -> "{" + q + "img" + q + ":{}"
                "advertise", "ad_content" -> "{" + q + "adv" + q + ":[]}"
                else -> null
            }
        }
        /**
         * 前端 HttpUtil.tryDecryption 的逆过程：
         * key = ASCII(md5(KEY_SEED))（32 字节 → AES-256），ECB + PKCS7，
         * 密文 Base64 包进 {"code":200,"data":...}。广告端点不带 time，密钥为常量。
         */
        private fun buildBody(payload: String): String {
            val digest = MessageDigest.getInstance("MD5").digest(KEY_SEED.toByteArray(StandardCharsets.UTF_8))
            val hex = StringBuilder(32)
            for (b in digest) hex.append(String.format(Locale.ROOT, "%02x", b))
            val key = SecretKeySpec(hex.toString().toByteArray(StandardCharsets.UTF_8), "AES")
            val cipher = Cipher.getInstance("AES/ECB/PKCS5Padding")
            cipher.init(Cipher.ENCRYPT_MODE, key)
            val data = Base64.encodeToString(
                cipher.doFinal(payload.toByteArray(StandardCharsets.UTF_8)), Base64.NO_WRAP
            )
            val q = '"'
            return "{" + q + "code" + q + ":200," + q + "data" + q + ":" + q + data + q + "}"
        }
        /** 请求头大小写不敏感查找。 */
        private fun header(map: Map<String, String>?, name: String): String? =
            map?.entries?.firstOrNull { it.key != null && it.key.equals(name, ignoreCase = true) }?.value
    }

    // ------------------------------------------------------------------ 生命周期
    override fun onModuleLoaded(param: ModuleLoadedParam) {
        sApi = this
        sProcessName = param.processName
        Config.initInHost(this)
    }
    /**
     * 热重载请求（autoHotReload / 服务触发），跑在<旧>代码里。
     * API 102 契约：返回 true 前让模块自有线程退场——停机标志 + interrupt + 有界 join
     *（线程只在 sleep 边界秒回；HTTP 自带 15s 超时，20s 未退场仍放行并记日志）。
     */
    override fun onHotReloading(param: HotReloadingParam): Boolean {
        val t = AutoCheckin.stopForHotReload()
        if (t != null) {
            try {
                t.join(20_000L)
            } catch (ignore: InterruptedException) {
                Thread.currentThread().interrupt()
            }
            if (t.isAlive) {
                log(TAG + " 热重载：签到线程 20s 未退场（阻塞在 HTTP），仍放行重载；" +
                        "纯 JVM 线程无 JNI/native 风险，旧代随线程结束自然回收")
            }
        }
        return true
    }
    /**
     * 热重载完成，跑在<新>代码里。包生命周期回调不会重放：
     * 按 hook id 把旧 handle replaceHook 成本代 hooker（链快照式原子替换，零空窗）；
     * 不认识/无 id 的旧 hook 一律 unhook——绝不让旧代代码留在链上吊住旧 classloader。
     * 本代不走 onModuleLoaded，静态引用在此补种。
     * 已知边界：Application.attach 已过点，热重载当次不重排签到（run_date 在宿主 prefs）。
     */
    override fun onHotReloaded(param: HotReloadedParam) {
        sApi = this
        sProcessName = param.processName
        Config.initInHost(this)
        var replaced = 0
        var dropped = 0
        for (h in param.oldHookHandles) {
            val k = hookerForId(h.id)
            if (k == null) {
                h.unhook()
                dropped++
                continue
            }
            try {
                h.replaceHook(k)
                replaced++
            } catch (t: Throwable) {
                log(TAG + " 热重载替换失败（已卸旧 hook）: " + t)
                try {
                    h.unhook()
                } catch (ignore: Throwable) {
                }
                dropped++
            }
        }
        log(TAG + " 热重载完成: 替换 " + replaced + " 个 hook, 卸载 " + dropped +
                " 个 (process=" + sProcessName + ")")
    }
    /** 按 hook id 重建本代等价 hooker；不认识的 id 返回 null。 */
    private fun hookerForId(id: String?): Hooker? = when (id) {
        H_SIR_WEBVIEW -> afterIntercept(1)
        H_SIR_SW -> afterIntercept(0)
        H_PAGE + ".start", H_PAGE + ".finish" -> pageHooker()
        H_ATTACH -> attachHooker()
        else -> null
    }
    override fun onPackageReady(param: PackageReadyParam) {
        // ① 过滤：只处理目标 App（回调对作用域内每个包都触发）
        if (param.packageName != TARGET_PKG) return
        val loader = param.classLoader
        val appInfo = param.applicationInfo
        // ② 自检日志：logcat 出现这行 = 模块加载成功
        log(TAG + " 已加载进 " + param.packageName + " (process=" + sProcessName + ")")
        // ③④ 网络层 A/B（去广告开关门控）
        if (Config.enabled(Config.K_AD_BLOCK)) {
            hookSirWebview(loader, appInfo)
            hookSirServiceWorker(loader, appInfo)
        } else {
            log(TAG + " 去广告开关已关（设置面板），跳过网络层 Hook")
        }
        // ⑤ 页面层：注入 JS 补丁（补丁内部按开关裁剪 fetch 桥/ad_free/自动跳线）
        if (Config.enabled(Config.K_AD_BLOCK) || Config.enabled(Config.K_T2S)) {
            try {
                val q = Class.forName("com.getcapacitor.q", false, loader)
                hookPageMethods(q)
                log(TAG + " 已 Hook q.onPageStarted/onPageFinished（JS 注入）")
            } catch (t: Throwable) {
                // ⑥ 兜底一：DexKit 按结构签名重新定位页面方法所在类
                log(TAG + " Hook q 页面方法失败，转 DexKit 定位: " + t)
                var dexkitPageOk = false
                try {
                    val pc = dexKitFindClass(loader, appInfo.sourceDir, "android.webkit.WebViewClient",
                        "onPageStarted", "android.webkit.WebView", "java.lang.String", "android.graphics.Bitmap")
                    if (pc != null) {
                        hookPageMethods(pc)
                        dexkitPageOk = true
                        log(TAG + " DexKit 兜底已 Hook " + pc.name + ".onPageStarted/onPageFinished（JS 注入）")
                    }
                } catch (t2: Throwable) {
                    log(TAG + " DexKit 页面层兜底失败: " + t2)
                }
                if (!dexkitPageOk) {
                    // ⑦ 兜底二：框架级 Hook（q 调用了 super 仍会触发；JS 幂等）
                    try {
                        hookPageMethods(WebViewClient::class.java)
                        log(TAG + " 已 Hook WebViewClient 框架级页面注入（兜底）")
                    } catch (t2: Throwable) {
                        log(TAG + " 框架级页面注入也失败: " + t2)
                    }
                }
            }
        }
        // ⑧ 自动签到调度（开关在 attachHooker 内每次实时判断；只挂主进程）
        if (sProcessName == TARGET_PKG) {
            try {
                hook(Application::class.java.getDeclaredMethod("attach", Context::class.java))
                    .setExceptionMode(XposedInterface.ExceptionMode.PROTECTIVE)
                    .setId(H_ATTACH)
                    .intercept(attachHooker())
                log(TAG + " 已挂 Application.attach（自动签到调度）")
            } catch (t: Throwable) {
                log(TAG + " 自动签到 hook 失败: " + t)
            }
        }
    }
    /** 网络层 A：com.getcapacitor.q.shouldInterceptRequest(WebView, WebResourceRequest)。 */
    private fun hookSirWebview(loader: ClassLoader, appInfo: ApplicationInfo) {
        try {
            val m = Class.forName("com.getcapacitor.q", false, loader)
                .getDeclaredMethod("shouldInterceptRequest", WebView::class.java, WebResourceRequest::class.java)
            hookSir(m, 1, "com.getcapacitor.q")
        } catch (t: Throwable) {
            log(TAG + " Hook q.shouldInterceptRequest 失败，转 DexKit 定位: " + t)
            try {
                val wc = dexKitFindClass(loader, appInfo.sourceDir, "android.webkit.WebViewClient",
                    "shouldInterceptRequest", "android.webkit.WebView", "android.webkit.WebResourceRequest")
                if (wc != null) {
                    hookSir(wc.getDeclaredMethod("shouldInterceptRequest",
                        WebView::class.java, WebResourceRequest::class.java), 1, wc.name)
                } else {
                    log(TAG + " DexKit 未找到 WebViewClient 子类，网络层 A 失效")
                }
            } catch (t2: Throwable) {
                log(TAG + " DexKit 网络层 A 兜底失败: " + t2)
            }
        }
    }
    /** 网络层 B：ServiceWorkerClient.shouldInterceptRequest(WebResourceRequest)。 */
    private fun hookSirServiceWorker(loader: ClassLoader, appInfo: ApplicationInfo) {
        // jadx 因 Windows 大小写不敏感把 com.getcapacitor.d 改名 C0099d，dex 真名是 com.getcapacitor.d
        try {
            val m = Class.forName("com.getcapacitor.d", false, loader)
                .getDeclaredMethod("shouldInterceptRequest", WebResourceRequest::class.java)
            hookSir(m, 0, "com.getcapacitor.d (ServiceWorker)")
        } catch (t: Throwable) {
            log(TAG + " Hook d.shouldInterceptRequest 失败，转 DexKit 定位: " + t)
            try {
                val sc = dexKitFindClass(loader, appInfo.sourceDir, "android.webkit.ServiceWorkerClient",
                    "shouldInterceptRequest", "android.webkit.WebResourceRequest")
                if (sc != null) {
                    hookSir(sc.getDeclaredMethod("shouldInterceptRequest", WebResourceRequest::class.java),
                        0, sc.name + " (ServiceWorker)")
                } else {
                    log(TAG + " DexKit 未找到 ServiceWorkerClient 子类，网络层 B 失效")
                }
            } catch (t2: Throwable) {
                log(TAG + " DexKit 网络层 B 兜底失败: " + t2)
            }
        }
    }
    private fun hookSir(m: java.lang.reflect.Method, argIndex: Int, label: String) {
        val id = if (argIndex == 1) H_SIR_WEBVIEW else H_SIR_SW
        hook(m).setExceptionMode(XposedInterface.ExceptionMode.PROTECTIVE)
            .setId(id).intercept(afterIntercept(argIndex))
        log(TAG + " 已 Hook " + label + ".shouldInterceptRequest")
    }
    /** 对目标类挂 onPageStarted/onPageFinished（id 加后缀区分，热重载按 id 重建）。 */
    private fun hookPageMethods(c: Class<*>) {
        hook(c.getDeclaredMethod("onPageStarted", WebView::class.java, String::class.java, Bitmap::class.java))
            .setExceptionMode(XposedInterface.ExceptionMode.PROTECTIVE)
            .setId(H_PAGE + ".start").intercept(pageHooker())
        hook(c.getDeclaredMethod("onPageFinished", WebView::class.java, String::class.java))
            .setExceptionMode(XposedInterface.ExceptionMode.PROTECTIVE)
            .setId(H_PAGE + ".finish").intercept(pageHooker())
    }
    // ------------------------------------------------------------------ Hookers
    /** Application.attach 的 after hooker：宿主拿到 Context 时调度自动签到（开关实时判断）。 */
    private fun attachHooker(): Hooker = Hooker { chain ->
        val original = chain.proceed()
        try {
            AutoCheckin.schedule(chain.getArg(0) as Context)
        } catch (t: Throwable) {
            log(TAG + " 自动签到调度失败: " + t)
        }
        original
    }
    /** 页面 Hooker：页面提交/结束时把 JS 补丁 evaluate 进主框架（补丁幂等，重复无害）。 */
    private fun pageHooker(): Hooker = Hooker { chain ->
        val original = chain.proceed()
        try {
            val wv = chain.getArg(0)
            if (wv is WebView) {
                val patch = buildPatch()
                if (Config.enabled(Config.K_T2S)) {
                    val t2s = t2sScript()
                    wv.evaluateJavascript(if (t2s == null) patch else patch + "\n" + t2s, null)
                } else {
                    wv.evaluateJavascript(patch, null)
                }
            }
        } catch (t: Throwable) {
            log(TAG + " JS 注入失败: " + t)
        }
        original
    }
    /**
     * after-hook：命中广告端点即用伪造响应覆盖返回值（无论原结果是否为 null）。
     * argIndex：WebResourceRequest 参数下标（WebViewClient 版=1，ServiceWorkerClient 版=0）。
     */
    private fun afterIntercept(argIndex: Int): Hooker = Hooker { chain ->
        val original = chain.proceed()
        try {
            val req = chain.getArg(argIndex) as? WebResourceRequest ?: return@Hooker original
            val payload = adPayloadFor(req.url) ?: return@Hooker original
            val isOptions = "OPTIONS".equals(req.method, ignoreCase = true)
            log(TAG + " 拦截广告请求 " + req.method + " " + req.url +
                    (if (isOptions) " (CORS 预检)" else " -> " + payload))
            buildResponse(req, payload, isOptions)
        } catch (t: Throwable) {
            // Hook 回调必须 try-catch：抛出去会崩宿主（PROTECTIVE 也兜底，双保险）
            log(TAG + " 拦截异常: " + t)
            original
        }
    }
    /** 构造 200 JSON 响应：GET 带加密空载荷体；OPTIONS（CORS 预检）返回 204 空体。 */
    @Throws(Exception::class)
    private fun buildResponse(req: WebResourceRequest, payload: String, options: Boolean): WebResourceResponse {
        val reqHeaders = req.requestHeaders
        val headers = HashMap<String, String>()
        // CORS：页面源 http://localhost（capacitor androidScheme=http），跨域必走预检。
        // 回显 Origin（带凭据时 "*" 不合法）与预检的 Access-Control-Request-Headers。
        val origin = header(reqHeaders, "Origin")
        if (!origin.isNullOrEmpty()) {
            headers["Access-Control-Allow-Origin"] = origin
            headers["Access-Control-Allow-Credentials"] = "true"
            headers["Vary"] = "Origin"
        } else {
            headers["Access-Control-Allow-Origin"] = "*"
        }
        val requested = header(reqHeaders, "Access-Control-Request-Headers")
        headers["Access-Control-Allow-Headers"] =
            if (!requested.isNullOrEmpty()) requested
            else "tokenparam, token, authorization, cookie, content-type, accept, origin"
        headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
        headers["Access-Control-Max-Age"] = "86400"
        headers["Content-Type"] = "application/json; charset=utf-8"
        headers["Cache-Control"] = "no-store"
        val body = if (options) ByteArray(0) else buildBody(payload).toByteArray(StandardCharsets.UTF_8)
        val status = if (options) 204 else 200
        val reason = if (options) "No Content" else "OK"
        return WebResourceResponse("application/json", "UTF-8", status, reason, headers, ByteArrayInputStream(body))
    }
}